import{_ as o,c,o as d,ag as l}from"./chunks/framework.D2yFLINz.js";const p=JSON.parse('{"title":"更新日志","description":"ew-color-picker 各版本的变更记录，含修复、新增与文档修正。","frontmatter":{"title":"更新日志","description":"ew-color-picker 各版本的变更记录，含修复、新增与文档修正。"},"headers":[],"relativePath":"zh/guide/changelog.md","filePath":"zh/guide/changelog.md"}'),a={name:"zh/guide/changelog.md"};function i(r,e,t,n,h,s){return d(),c("div",null,[...e[0]||(e[0]=[l('<h1 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h1><h2 id="_2-0-8" tabindex="-1">2.0.8 <a class="header-anchor" href="#_2-0-8" aria-label="Permalink to &quot;2.0.8&quot;">​</a></h2><h3 id="修复" tabindex="-1">修复 <a class="header-anchor" href="#修复" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>修复通过 <code>&lt;link&gt;</code> 引入静态 CSS 时箭头和关闭图标位置错乱的问题：图标样式之前只由 core 入口在运行时注入，SCSS 构建产物（<code>@ew-color-picker/style</code>）中缺失，导致箭头偏移。现在 SCSS 源文件中也包含了这些规则</li><li>箭头图标 <code>fill</code> 从硬编码的 <code>#666666</code> 改为 <code>currentColor</code>，图标可继承主题文字颜色</li><li>修复 <code>hasBox: false</code> 配合 <code>appendTo</code> 时空的 root 容器仍占用 <code>line-height</code> 高度的问题：<code>.ew-color-picker</code> 空壳现在通过 <code>:empty { display: none }</code> 隐藏，盒子渲染后自动恢复显示</li><li>修复 <code>hasBox: false</code> 时面板定位错误：定位锚点现在从 box 回退到用户传入的 <code>el</code> 容器（最后才回退到 root），不再以 0 尺寸的空壳为参照</li><li>修复 <code>showPanel</code>/<code>hidePanel</code> 非幂等问题：面板已打开时再次调用 <code>showPanel</code> 会重新执行打开动画，动画先将高度重置为 <code>0</code>，视觉上表现为面板关闭。现在两个方法在面板已处于目标状态时直接返回</li></ul><h3 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to &quot;文档&quot;">​</a></h3><ul><li>中英文 README 新增 npm 版本、下载量、许可证、构建状态、TypeScript、Stars 徽章</li><li>中英文 README 新增在线演示截图</li></ul><h2 id="_2-0-7" tabindex="-1">2.0.7 <a class="header-anchor" href="#_2-0-7" aria-label="Permalink to &quot;2.0.7&quot;">​</a></h2><h3 id="修复-1" tabindex="-1">修复 <a class="header-anchor" href="#修复-1" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>修复颜色选择器面板在 Element Plus Dialog 等弹层容器中被遮罩层遮挡的问题：面板 <code>z-index</code> 此前在样式表中固定为 <code>1000</code>，而弹层组件库从 <code>2000</code> 起步且每次打开递增。现在每次打开面板都会自动将内联层级提升为「祖先最大层级 + 1」，普通页面仍由样式表默认值控制，样式读写异常时静默降级</li></ul><h3 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h3><ul><li>新增弹层容器内自动提升层级、重复打开重新计算、普通页面不写内联样式的回归用例</li></ul><h2 id="_2-0-6" tabindex="-1">2.0.6 <a class="header-anchor" href="#_2-0-6" aria-label="Permalink to &quot;2.0.6&quot;">​</a></h2><h3 id="修复-2" tabindex="-1">修复 <a class="header-anchor" href="#修复-2" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>修复 <code>colorRgbaToHsva</code> 把合法的透明度 <code>0</code> 转成 <code>1</code> 的问题（<code>parseFloat(...) || 1</code> 把 <code>0</code> 当成了假值）；该问题会导致全透明颜色在拖动色相或饱和度/明度后变不透明，<code>getHsvaColor()</code> 也会返回 <code>a: 1</code></li><li>修复 <code>colorRgbaToHsla</code> 返回的 <code>colorObj.h</code> 停留在内部 <code>0-6</code> 扇区值而非角度值的问题，避免 <code>colorHslaToRgba</code> 往返转换错色（如绿色 <code>rgba(0, 202, 136, 1)</code> 被还原成 <code>rgba(204, 10, 0, 1)</code>）</li></ul><h3 id="测试-1" tabindex="-1">测试 <a class="header-anchor" href="#测试-1" aria-label="Permalink to &quot;测试&quot;">​</a></h3><ul><li>新增回归测试：<code>rgba(..., 0)</code> 往返转换、透明度无法解析时的回退、HSL 色相与往返转换</li></ul><h3 id="发布" tabindex="-1">发布 <a class="header-anchor" href="#发布" aria-label="Permalink to &quot;发布&quot;">​</a></h3><ul><li>新增 GitHub Actions CI：在推送和 PR 到 <code>master</code> 时执行依赖安装、全量测试与全量构建</li><li>为 <code>utils</code> 和 <code>core</code> 声明 <code>rimraf</code> 开发依赖，修复 pnpm 严格 <code>node_modules</code> 结构下清理脚本找不到命令的问题</li></ul><h2 id="_2-0-5" tabindex="-1">2.0.5 <a class="header-anchor" href="#_2-0-5" aria-label="Permalink to &quot;2.0.5&quot;">​</a></h2><h3 id="修复-3" tabindex="-1">修复 <a class="header-anchor" href="#修复-3" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>修复面板在抽屉、弹窗、滚动容器内的定位问题：新增 <code>boundary</code> 配置项，支持传入 CSS 选择器或 HTMLElement，面板会被限制在该容器的可视区域内，而非仅按视口夹取</li><li>修复 <code>destroy()</code> 后 <code>setTimeout</code> 回调仍绑定 <code>document.mousedown</code> 监听导致泄漏的问题：回调现在会先检查实例是否已销毁</li><li>修复根目录 <code>build:xxx</code> 快捷命令静默失败的问题（<code>pnpm -r build:xxx</code> 匹配不到任何子包脚本）；改为 <code>pnpm --filter &lt;pkg&gt; build</code>，并补齐 gradient、select、checkbox、copy-color、input-number 的快捷命令</li></ul><h3 id="优化" tabindex="-1">优化 <a class="header-anchor" href="#优化" aria-label="Permalink to &quot;优化&quot;">​</a></h3><ul><li>拖拽逻辑收口到 <code>utils/drag.ts</code>：新增 <code>getRatio</code>、<code>bindMouseDrag</code>、<code>bindTouchDrag</code> 工具函数，hue、alpha、panel、gradient 四包复用，消除约 10 处 <code>as EventListener</code> 强转</li><li>提取 <code>DEFAULT_PANEL_WIDTH</code> / <code>DEFAULT_PANEL_HEIGHT</code> 常量，替换 panel 和 gradient 中 7 处硬编码的 <code>285 / 180</code></li><li>统一使用工具函数：<code>isString</code> / <code>isObject</code> / <code>isBoolean</code> / <code>isNumber</code> 替代原生 <code>typeof</code> 判断；<code>$</code> 和 <code>getRect</code> 替代直接调用 <code>querySelector</code> / <code>getBoundingClientRect</code></li><li>去掉插件 options 初始化中的 <code>as any</code> 强转；<code>install(core: any)</code> 统一为 <code>install(core: ewColorPicker)</code></li><li><code>getPrefix</code> 改用 <code>isString</code> 并明确接收 <code>ewColorPicker</code> 实例类型，替代 <code>any</code></li><li>删除 utils 中未使用的 <code>eventType</code> 死代码</li><li>补充 <code>applyOrder</code> 排序规则的注释：未声明 <code>applyOrder</code> 的插件默认按 0 处理，先于所有 <code>Post</code> 插件执行</li></ul><h3 id="文档-1" tabindex="-1">文档 <a class="header-anchor" href="#文档-1" aria-label="Permalink to &quot;文档&quot;">​</a></h3><ul><li>新增 <code>boundary</code> 配置项的中英文文档及使用示例</li><li>新增示例页 <code>18-panel-boundary.html</code>，演示容器内面板定位</li><li>修复文档站英文版底部友情链接显示中文的问题</li><li>补齐 examples 导航中缺失的 15-18 号链接</li></ul><h3 id="发布-1" tabindex="-1">发布 <a class="header-anchor" href="#发布-1" aria-label="Permalink to &quot;发布&quot;">​</a></h3><ul><li>所有包添加 <code>prepublishOnly: &quot;npm run build&quot;</code>，确保每次发布前自动构建最新产物</li></ul><h2 id="_2-0-4" tabindex="-1">2.0.4 <a class="header-anchor" href="#_2-0-4" aria-label="Permalink to &quot;2.0.4&quot;">​</a></h2><h3 id="新增" tabindex="-1">新增 <a class="header-anchor" href="#新增" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>新增 <code>@ew-color-picker/select</code> 下拉选择组件与插件：支持自定义选项、占位符、尺寸、键盘操作、外部点击关闭与 ARIA 无障碍规范，可通过 <code>selectClearable</code> 开启清空图标，配置项含 <code>selectItems</code> / <code>selectValue</code> / <code>selectPlaceholder</code> / <code>onSelectChange</code> / <code>onSelectClear</code>，仅在 <code>selectItems</code> 非空时渲染</li><li>新增 <code>@ew-color-picker/gradient</code> 渐变插件：提供可拖拽色标的渐变编辑器，支持线性 / 径向 / 锥形、重复渐变、角度与位置、双位置色标，以及 <code>srgb</code> / <code>srgb-linear</code> / <code>hsl</code> / <code>oklab</code> / <code>oklch</code> 插值提示。CSS 字符串可通过 <code>parseGradient</code> / <code>serializeGradient</code> 稳定回环，默认仅在 <code>showGradient: true</code> 或提供 <code>gradient</code> / <code>gradientStops</code> 时渲染</li><li>新增 <code>@ew-color-picker/checkbox</code> 复选框组件与插件：用主题化方块替代原生复选框外观，底层保留原生 input 以维持语义与键盘操作。插件在提供 <code>checkboxLabel</code> 时渲染到面板底部行，支持 <code>showCheckbox</code> / <code>checkboxChecked</code> / <code>checkboxDisabled</code> / <code>onCheckboxChange</code></li><li>聚合包新增 <code>createEwColorPicker(options)</code> 工厂函数导出，兼容入口包 <code>ew-color-picker</code> 同步支持该导出</li></ul><h3 id="修复-4" tabindex="-1">修复 <a class="header-anchor" href="#修复-4" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>修复 <code>defaultColor</code> 的判断逻辑：此时实例插件尚未创建，改为按静态插件注册表判断 alpha 插件是否已注册；未启用 alpha 时，rgba 格式的默认值正确降级为 hex</li><li>修复无初始颜色或延迟设置颜色时打开面板，色相柱背景、面板光标与色相 / 透明度滑块位置不正确的问题：面板显示后会按当前颜色重新同步定位</li><li>修复色相柱与透明度柱在不同方向组合下面板宽度计算不准确，导致同排元素换行、左右边缘无法对齐的问题</li><li>修复 <code>colorRgbaToHsva</code> 只接受 rgba 字符串的问题，现在兼容 hex / rgb / 颜色关键字等输入</li><li>修复渐变编辑器停靠点行的布局问题：数字输入框数值被裁剪、删除 / 新增按钮被挤到下一行；输入框加宽并压缩步进按钮宽度与行间距后，单行内完整展示</li></ul><h2 id="_2-0-3" tabindex="-1">2.0.3 <a class="header-anchor" href="#_2-0-3" aria-label="Permalink to &quot;2.0.3&quot;">​</a></h2><blockquote><p>本版本已发布到 npm，文档站已同步更新。</p></blockquote><h3 id="新增-1" tabindex="-1">新增 <a class="header-anchor" href="#新增-1" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>新增 <code>@ew-color-picker/eyedropper</code> 吸管插件：基于浏览器原生 EyeDropper API 从屏幕任意位置取色，自动检测能力，通过 <code>core.setColor()</code> 写回结果，支持 <code>showEyedropper</code> / <code>eyedropperText</code> / <code>onEyedropperPick</code>，用户取消时静默忽略 <code>AbortError</code></li><li>新增 <code>@ew-color-picker/copy-color</code> 复制颜色插件：一键复制当前颜色到剪贴板。按钮底色跟随当前颜色并按对比度自动切换图标颜色，优先使用异步剪贴板 API，失败时降级到 <code>execCommand</code>，复制成功后弹出内置提示气泡，支持 <code>showCopyColor</code> / <code>copyColorText</code> / <code>copiedText</code> / <code>onCopyColor</code></li><li>吸管按钮与复制按钮改为放在颜色值输入框上方的独立工具栏行，不再与输入框、清空 / 确定按钮挤在同一行</li></ul><h3 id="修复-5" tabindex="-1">修复 <a class="header-anchor" href="#修复-5" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>修复数字输入框步进按钮的上下箭头：补齐图标类名并将尺寸调整为 10px，图标现在完全居中，不再溢出被分割线裁剪</li><li>修复 RGB / HSL 分通道输入框首次点击上下箭头时颜色值被重置为 0 的问题：颜色变化时同步输入框内部值，加减从当前通道值开始计算</li></ul><h2 id="_2-0-2" tabindex="-1">2.0.2 <a class="header-anchor" href="#_2-0-2" aria-label="Permalink to &quot;2.0.2&quot;">​</a></h2><h3 id="修复-6" tabindex="-1">修复 <a class="header-anchor" href="#修复-6" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>发布产物中的内部依赖改为指向对应版本（<code>^2.0.2</code>），不再沿用旧的 <code>^2.0.0</code> 范围。避免 2.0.1 的插件解析到旧版 <code>@ew-color-picker/utils</code>，导致 <code>getPrefix</code> 不存在而启动报错</li></ul><h2 id="_2-0-1" tabindex="-1">2.0.1 <a class="header-anchor" href="#_2-0-1" aria-label="Permalink to &quot;2.0.1&quot;">​</a></h2><blockquote><p>本版本已发布到 npm，并同步到文档站。</p></blockquote><h3 id="修复-7" tabindex="-1">修复 <a class="header-anchor" href="#修复-7" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>修复插件开关失效：<code>ewColorPickerPanel: false</code>、<code>ewColorPickerColorMode: false</code>（或对象配置）被默认配置覆盖，实际不生效</li><li>面板容器补充 <code>box-sizing: content-box</code>，不再依赖宿主全局 <code>box-sizing</code> 重置</li><li>移除按视口宽度（<code>max-width: 768px</code>）写死面板、输入框、预设区尺寸的媒体查询，内部尺寸统一由 <code>--panel-width</code> / <code>--panel-height</code> 控制</li><li>预定义色板改为 flex 自动换行，移除硬编码的「每行 10 个」换行规则，修复色块数量与容器宽度不匹配时的错误换行</li><li><code>use()</code> 改为按 <code>pluginName</code> 去重，避免 HMR、重复 import 或多入口场景重复注册同一插件</li><li>插件构造异常改为通过 <code>console.warn</code> 输出插件名与错误信息，不再静默吞掉，便于自定义插件调试</li></ul><h3 id="新增-2" tabindex="-1">新增 <a class="header-anchor" href="#新增-2" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li><code>appendTo</code> 选项：把面板容器挂载到 <code>document.body</code> 或任意容器，避免被弹窗、抽屉、滚动容器的 <code>overflow</code> 裁剪。启用后面板改为相对视口定位，仍按 <code>panelPlacement</code> 计算并做边界翻转，滚动或窗口尺寸变化时自动重算</li><li><code>prefix</code> 选项：自定义全部 CSS 类名前缀（默认 <code>ew-</code>），方便嵌入其他库时避免样式冲突。SCSS 同步提供 <code>$prefix</code> 构建变量，需与 JS 选项保持一致</li><li><code>ApplyOrder</code> 由 <code>const enum</code> 改为普通枚举，可直接从 <code>@ew-color-picker/utils</code> 运行时导入，编写自定义插件时无需手写 <code>&#39;pre&#39;</code> / <code>&#39;post&#39;</code> 字符串</li></ul><h3 id="文档-2" tabindex="-1">文档 <a class="header-anchor" href="#文档-2" aria-label="Permalink to &quot;文档&quot;">​</a></h3><ul><li>修正预定义色板、数字输入框的类名，与源码保持一致</li><li>移除不存在的 <code>ewColorPickerBox</code> 嵌套配置写法，统一为顶层选项</li><li>修正 <code>autoPanelPosition</code> 的生效前提说明</li><li>新增 <code>appendTo</code> 选项说明（中英文）</li><li>新增 <code>prefix</code> 选项说明（中英文），含 SCSS 自定义编译示例</li><li>补充 <code>applyOrder</code> 执行顺序说明与用法示例（中英文）</li><li>文档站默认语言改为英文，中文文档迁移到 <code>/zh/</code> 路径，README 默认展示英文版</li></ul><h2 id="_2-0-0" tabindex="-1">2.0.0 <a class="header-anchor" href="#_2-0-0" aria-label="Permalink to &quot;2.0.0&quot;">​</a></h2><p>首个正式发布版本：核心 + 插件架构、14 个包（13 个 scoped 包 + 无 scope 兼容入口包 <code>ew-color-picker</code>）、双语文档站与在线演示。</p>',51)])])}const b=o(a,[["render",i]]);export{p as __pageData,b as default};
